from pathlib import PurePosixPath
def solve(value):
    path = PurePosixPath(value)
    if path.is_absolute() or '..' in path.parts:
        raise ValueError('unsafe relative path')
    return str(path)

retry-budget:
def solve(operation, attempts):
    if attempts < 1:
        raise ValueError('attempts must be positive')
    for index in range(attempts):
        try:
            return operation()
        except ValueError:
            if index == attempts - 1:
                raise

rolling-window:
from collections import deque
def solve(values, width):
    if width < 1:
        raise ValueError('width must be positive')
    window = deque(maxlen=width)
    result = []
    for value in values:
        window.append(value)
        if len(window) == width:
            result.append(tuple(window))
    return result

strict-json-lines:
import json
def solve(text):
    def invalid(value):
        raise ValueError('nonfinite JSON constant')
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if line.strip():
            try:
                result.append(json.loads(line, parse_constant=invalid))
            except ValueError as error:
                raise ValueError('invalid JSON on line ' + str(number)) from error
    return result

utc-sort:
from datetime import datetime, timezone
def solve(values):
    def key(value):
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
        return parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed
    return sorted(values, key=key)

