nested-redaction:
def solve(value):
    if isinstance(value, dict):
        return {key: '[REDACTED]' if key.casefold() in {'password', 'token', 'secret'} else solve(item)
                for key, item in value.items()}
    if isinstance(value, list):
        return [solve(item) for item in value]
    return value

topological-order:
import heapq
def solve(nodes, edges):
    nodes = set(nodes)
    outgoing = {node: set() for node in nodes}
    indegree = dict.fromkeys(nodes, 0)
    for before, after in edges:
        if before not in nodes or after not in nodes:
            raise ValueError('unknown node')
        if after not in outgoing[before]:
            outgoing[before].add(after)
            indegree[after] += 1
    ready = [node for node in nodes if not indegree[node]]
    heapq.heapify(ready)
    result = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for after in sorted(outgoing[node]):
            indegree[after] -= 1
            if not indegree[after]:
                heapq.heappush(ready, after)
    if len(result) != len(nodes):
        raise ValueError('cycle')
    return result
